from jsmed.all_specialists import get_specialist
from symphony_response import assert_incomplete_request_block
import re
import os
import json
import socket
lycl = get_specialist()

def get_setting(setting_name):
    return os.environ.get(setting_name)

def query_expert(payload):
    return lycl.ask(payload)

def build_response(intent, entities):
    return {'intent': intent, 'entities': entities}

def main():
    response = query_expert("I need help with depression drugs")
    return response['response']

def respond(event):
    intent = event['intent']
    entities = event['entities']

    if intent in {'get_med', 'manage_med', 'what_med'}:
        return build_response(intent, entities)


if __name__ == "__main__":
    main()
